// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        uint256 before = c.balances(actor);
        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, withdrawAmount));
        assertTrue(ok);

        uint256 afterBal = c.balances(actor);
        // Universal rule: a successful CashOut(_am) with _am <= balance decreases
        // the sender's balance by exactly _am.
        assertTrue(afterBal == before - withdrawAmount);
    }
}

contract InvMutTest
{
    C c;
    constructor(C _c) { c = _c; }

    function testDeposit() public
    {
        uint amount = c.MinDeposit();
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        bool ok = true;
        c.CashOut(amount);
        assert(ok);
    }
    receive() external payable {}
}
